import {
  afterNextRender,
  ChangeDetectionStrategy,
  Component,
  inject,
  Injector,
  input,
  OnChanges,
  OnDestroy,
  output,
  signal,
} from '@angular/core';
import { FormControl, FormRecord, ReactiveFormsModule } from '@angular/forms';
import {
  isKindValue,
  validateField,
  type DraftEntry,
  type FieldDefinition,
  type FieldValue,
  type FormDefinition,
} from '@quote/contract';
import type { Subscription } from 'rxjs';
import { QUOTE_CLOCK, QuoteState } from './quote-state';

@Component({
  selector: 'app-details-form',
  imports: [ReactiveFormsModule],
  changeDetection: ChangeDetectionStrategy.OnPush,
  templateUrl: './details-form.html',
})
export class DetailsForm implements OnChanges, OnDestroy {
  private readonly store = inject(QuoteState);
  private readonly clock = inject(QUOTE_CLOCK);
  private readonly injector = inject(Injector);
  readonly configuration = input.required<FormDefinition>();
  readonly complete = output<void>();
  protected readonly errors = signal<Record<string, string>>({});
  protected readonly announcement = signal('');
  protected form = new FormRecord<FormControl<FieldValue | null>>({});
  private changes?: Subscription;
  private announcer?: ReturnType<typeof setTimeout>;
  private readonly touched = new Set<string>();
  private readonly badInput = new Set<string>();
  private submitted = false;

  ngOnChanges() {
    this.changes?.unsubscribe();
    this.clearAnnouncement();
    this.errors.set({});
    this.touched.clear();
    this.badInput.clear();
    this.submitted = false;
    const config = this.configuration();
    const draft = this.store.draft(config.country);
    this.form = new FormRecord(
      Object.fromEntries(
        config.fields.map((field) => [
          field.id,
          new FormControl<FieldValue | null>(
            draft[field.id]?.value ?? (field.kind === 'checkbox' ? false : null),
          ),
        ]),
      ),
    );
    this.changes = this.form.valueChanges.subscribe(() => this.save());
  }

  ngOnDestroy() {
    this.changes?.unsubscribe();
    this.clearAnnouncement();
  }

  protected controlId(field: FieldDefinition) {
    return `quote-field-${field.id}`;
  }

  protected description(field: FieldDefinition) {
    const id = this.controlId(field);
    const descriptions = [
      field.helpText && `${id}-help`,
      this.errors()[field.id] && `${id}-error`,
    ].filter(Boolean);
    return descriptions.join(' ') || null;
  }

  protected inputType(field: FieldDefinition) {
    if (field.kind === 'date') return field.kind;
    return field.rules.some((rule) => rule.operator === 'email') ? 'email' : 'text';
  }

  protected onInput(field: FieldDefinition, event: Event) {
    const input = event.target as HTMLInputElement;
    if (input.validity.badInput) this.badInput.add(field.id);
    else this.badInput.delete(field.id);
    if (this.touched.has(field.id) || this.submitted) this.recheck(field, true);
  }

  protected onBlur(field: FieldDefinition) {
    this.touched.add(field.id);
    this.recheck(field, true);
  }

  protected submit(event: Event) {
    event.preventDefault();
    this.submitted = true;
    this.clearAnnouncement();
    const fields = this.configuration().fields;
    const now = this.clock();
    const entries = fields.flatMap((field) => {
      const error = this.fieldError(field, now);
      return error ? [[field.id, error] as const] : [];
    });
    this.errors.set(Object.fromEntries(entries));
    if (entries.length) {
      afterNextRender(() => document.getElementById(`quote-field-${entries[0][0]}`)?.focus(), {
        injector: this.injector,
      });
      return;
    }
    this.save();
    this.complete.emit();
  }

  private save() {
    const config = this.configuration();
    const draft = Object.fromEntries(
      config.fields.map((field) => {
        const raw = this.form.controls[field.id].value;
        const value = raw === '' || !isKindValue(field.kind, raw) ? null : raw;
        return [field.id, { kind: field.kind, value } satisfies DraftEntry];
      }),
    );
    this.store.save(config.country, draft);
  }

  private fieldError(field: FieldDefinition, now: Date) {
    if (this.badInput.has(field.id)) return field.errorMessage;
    return validateField(field, this.form.controls[field.id].value, now)[0];
  }

  private recheck(field: FieldDefinition, announce: boolean) {
    const before = this.errors()[field.id];
    const error = this.fieldError(field, this.clock());
    if (before === error) return;
    this.errors.update((current) => {
      const next = { ...current };
      if (error) next[field.id] = error;
      else delete next[field.id];
      return next;
    });
    if (announce) {
      this.clearAnnouncement();
      if (error)
        this.announcer = setTimeout(() => this.announcement.set(`${field.label}: ${error}`), 250);
    }
  }

  private clearAnnouncement() {
    clearTimeout(this.announcer);
    this.announcement.set('');
  }
}
import { HttpClient } from '@angular/common/http';
import { inject, Injectable, InjectionToken, signal } from '@angular/core';
import {
  decodeForm,
  isFieldKind,
  isKindValue,
  isRecord,
  isSafeId,
  reconcileDraft,
  validateField,
  type Country,
  type DraftEntry,
  type FormDefinition,
  type QuoteDraft,
} from '@quote/contract';
import type { Subscription } from 'rxjs';

type LoadState =
  | { phase: 'idle' }
  | { phase: 'loading' | 'unavailable'; country: Country }
  | { phase: 'ready'; country: Country; form: FormDefinition; validation?: DraftValidation };

type DraftValidation = { date: string; invalidFields: readonly string[] };

export const QUOTE_CLOCK = new InjectionToken<() => Date>('quote calendar clock', {
  providedIn: 'root',
  factory: () => () => new Date(),
});

function civilDate(now: Date): string {
  return `${now.getFullYear()}-${now.getMonth() + 1}-${now.getDate()}`;
}

function evaluate(form: FormDefinition, draft: QuoteDraft, now: Date): DraftValidation {
  const invalidFields = form.fields
    .filter((field) => validateField(field, draft[field.id]?.value, now).length)
    .map((field) => field.id);
  return { date: civilDate(now), invalidFields };
}

function storageKey(country: Country) {
  return `quote-draft-v1:${country}`;
}

function restore(country: Country): QuoteDraft {
  try {
    const text = sessionStorage.getItem(storageKey(country));
    if (!text || text.length > 100_000) return {};
    const snapshot: unknown = JSON.parse(text);
    if (
      !isRecord(snapshot) ||
      snapshot['version'] !== 1 ||
      snapshot['country'] !== country ||
      !isRecord(snapshot['draft'])
    )
      return {};
    const entries = Object.entries(snapshot['draft']);
    if (entries.length > 40) return {};
    const draft: [string, DraftEntry][] = [];
    for (const [key, entry] of entries) {
      if (
        !isSafeId(key) ||
        !isRecord(entry) ||
        !isFieldKind(entry['kind']) ||
        (entry['value'] !== null && !isKindValue(entry['kind'], entry['value']))
      )
        return {};
      draft.push([key, { kind: entry['kind'], value: entry['value'] }]);
    }
    return Object.fromEntries(draft);
  } catch {
    return {};
  }
}

@Injectable({ providedIn: 'root' })
export class QuoteState {
  private readonly http = inject(HttpClient);
  private readonly clock = inject(QUOTE_CLOCK);
  private readonly current = signal<LoadState>({ phase: 'idle' });
  private readonly drafts = signal<Partial<Record<Country, QuoteDraft>>>({});
  private request?: Subscription;
  private generation = 0;

  readonly state = this.current.asReadonly();

  leave() {
    this.generation++;
    this.request?.unsubscribe();
    this.current.set({ phase: 'idle' });
  }

  load(country: Country, refresh = false) {
    const state = this.current();
    if (!refresh && state.phase !== 'idle' && state.country === country) return;
    const generation = ++this.generation;
    this.request?.unsubscribe();
    this.current.set({ phase: 'loading', country });

    const stillCurrent = () =>
      generation === this.generation &&
      this.current().phase === 'loading' &&
      this.currentCountry() === country;
    const unavailable = () => {
      if (stillCurrent()) this.current.set({ phase: 'unavailable', country });
    };
    this.request = this.http
      .get<unknown>(`/api/quote-content/v1/${country}/form`, {
        timeout: 10_000,
      })
      .subscribe({
        next: (input) => {
          if (!stillCurrent()) return;
          const now = this.clock();
          const form = decodeForm(input, country, now);
          if (!form) return unavailable();
          const draft = reconcileDraft(form.fields, this.draft(country));
          this.save(country, draft);
          this.current.set({
            phase: 'ready',
            country,
            form,
            validation: evaluate(form, draft, now),
          });
        },
        error: unavailable,
      });
  }

  private currentCountry(): Country | null {
    const state = this.current();
    return state.phase === 'idle' ? null : state.country;
  }

  draft(country: Country): QuoteDraft {
    return this.drafts()[country] ?? restore(country);
  }

  save(country: Country, draft: QuoteDraft) {
    this.drafts.update((drafts) => ({ ...drafts, [country]: draft }));
    const state = this.current();
    if (state.phase === 'ready' && state.country === country && state.validation) {
      this.current.set({ ...state, validation: undefined });
    }
    try {
      sessionStorage.setItem(storageKey(country), JSON.stringify({ version: 1, country, draft }));
    } catch {
      // The in-memory copy remains available for this page session.
    }
  }

  canContinue(country: Country): boolean {
    const state = this.current();
    if (state.phase !== 'ready' || state.country !== country) return false;
    const now = this.clock();
    const validation =
      civilDate(now) === state.validation?.date
        ? state.validation
        : evaluate(state.form, this.draft(country), now);
    return validation.invalidFields.length === 0;
  }
}
export const READ_FORM_ACTION = "api::quote-content.quote-content.readForm";

export default {
  routes: [
    {
      method: "GET",
      path: "/quote-content/v1/:country/form",
      handler: READ_FORM_ACTION,
      config: { auth: { scope: [READ_FORM_ACTION] } },
    },
  ],
};
import { isCountry } from "@quote/contract";
import { FORM_UID, projectForm } from "../form-projection";

type ReadContext = {
  params: Record<string, unknown>;
  querystring: string;
  set(name: string, value: string): void;
  status: number;
  body: unknown;
};

export default {
  async readForm(ctx: ReadContext) {
    ctx.set("Cache-Control", "no-store");
    const fail = (status: number, code: string) => {
      ctx.body = { error: { code } };
      ctx.status = status;
    };

    const country = ctx.params["country"];
    if (!isCountry(country)) return fail(404, "UNSUPPORTED_COUNTRY");
    if (ctx.querystring) return fail(400, "INVALID_REQUEST");

    let documents;
    try {
      documents = await strapi.documents(FORM_UID).findMany({
        status: "published",
        filters: { country },
        populate: { fields: { populate: ["options", "rules"] } },
        limit: 2,
      });
    } catch {
      strapi.log.error("Quote form document retrieval failed.");
      return fail(503, "CONTENT_UNAVAILABLE");
    }

    if (!documents.length) return fail(404, "FORM_NOT_PUBLISHED");
    const form =
      documents.length === 1 ? projectForm(documents[0], country) : null;
    if (!form) {
      strapi.log.warn("A published quote form configuration was rejected.");
      return fail(503, "FORM_UNAVAILABLE");
    }
    ctx.body = form;
    ctx.status = 200;
  },
};

