      ...common,
      kind,
      options: parsedOptions,
      ...(typeof value === "string" && { defaultValue: value }),
    };
  }
  if (options !== undefined) return null;
  switch (kind) {
    case "checkbox":
      if (value !== undefined && typeof value !== "boolean") return null;
      return {
        ...common,
        kind,
        ...(typeof value === "boolean" && { defaultValue: value }),
      };
    case "number":
      if (
        value !== undefined &&
        (typeof value !== "number" || !Number.isFinite(value))
      )
        return null;
      return {
        ...common,
        kind,
        ...(typeof value === "number" && { defaultValue: value }),
      };
    case "text":
    case "date":
      if (
        value !== undefined &&
        (typeof value !== "string" || !isKindValue(kind, value))
      )
        return null;
      return {
        ...common,
        kind,
        ...(typeof value === "string" && { defaultValue: value }),
      };
  }
}

function decodeField(input: unknown, now: Date): FieldDefinition | null {
  if (!isRecord(input)) return null;
  const {
    id,
    label,
    helpText,
    errorMessage,
    required,
    order,
    kind,
    purpose,
    rules,
    options,
    defaultValue,
  } = input;
  if (
    !isSafeId(id) ||
    !copy(label) ||
    !copy(helpText, true) ||
    !copy(errorMessage) ||
    typeof required !== "boolean" ||
    !boundedInteger(order) ||
    !isFieldKind(kind) ||
    !Array.isArray(rules) ||
    rules.length > MAX_RULES
  )
    return null;
