export function decodeForm(
  input: unknown,
  country: Country,
  now = new Date(),
): FormDefinition | null {
  if (
    !isRecord(input) ||
    input["schemaVersion"] !== 1 ||
    input["country"] !== country ||
    !Array.isArray(input["fields"]) ||
    input["fields"].length === 0 ||
    input["fields"].length > MAX_FIELDS
