  const lowerBounds = {
    min: "max",
    minDate: "maxDate",
    minLength: "maxLength",
  } as const;
  return rules.every((rule) => {
    if (
      rule.operator !== "min" &&
      rule.operator !== "minDate" &&
      rule.operator !== "minLength"
