function rulePasses(rule: Rule, value: FieldValue, now: Date): boolean {
  switch (rule.operator) {
    case "required":
      return true;
    case "email":
      return (
        typeof value === "string" && /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value)
      );
    case "minLength":
      return typeof value === "string" && [...value].length >= rule.argument;
    case "maxLength":
      return typeof value === "string" && [...value].length <= rule.argument;
    case "pattern":
      return typeof value === "string" && matchesPattern(rule.argument, value);
    case "min":
      return typeof value === "number" && value >= rule.argument;
    case "max":
      return typeof value === "number" && value <= rule.argument;
    case "minDate":
      return typeof value === "string" && value >= rule.argument;
    case "maxDate":
      return typeof value === "string" && value <= rule.argument;
    case "minimumAge":
      return typeof value === "string" && ageOn(value, now) >= rule.argument;
