import type { Core } from "@strapi/strapi";
import { FORM_UID } from "./api/quote-content/form-projection";
import { READ_FORM_ACTION } from "./api/quote-content/routes/quote-content";
import { seedForm } from "./seed-forms";

export default {
  async bootstrap({ strapi }: { strapi: Core.Strapi }) {
    const seedState = strapi.store({ type: "core", name: "quote-content" });
    if (await seedState.get({ key: "us01-seeded" })) return;

    const roles = strapi.db.query("plugin::users-permissions.role");
    const publicRole = await roles.findOne({ where: { type: "public" } });
    if (!publicRole)
      throw new Error(
        "The Public role is unavailable during quote initialization.",
      );
    const permissions = strapi.db.query("plugin::users-permissions.permission");
    const existing = await permissions.findOne({
      where: { action: READ_FORM_ACTION, role: publicRole.id },
    });
    if (!existing)
      await permissions.create({
        data: { action: READ_FORM_ACTION, role: publicRole.id },
      });

    for (const country of ["co", "cl"] as const) {
      const documents = strapi.documents(FORM_UID);
      const draft = await documents.findFirst({
        status: "draft",
        filters: { country },
      });
      if (!draft)
        await documents.create({
          data: seedForm(country),
          status: "published",
        });
    }
    await seedState.set({ key: "us01-seeded", value: true });
  },
};
import type { Country } from "@quote/contract";

const makeOptions = [
  { optionKey: "example-motor", label: "Ejemplo Motor" },
  { optionKey: "demo-auto", label: "Demo Auto" },
];
const nameField = {
  fieldKey: "holder-name",
  label: "Nombre del titular",
  kind: "text",
  order: 10,
  required: true,
  helpText: "",
  errorMessage: "Ingresa el nombre del titular.",
  rules: [
    {
      operator: "minLength",
      argument: { value: 2 },
      message: "Ingresa al menos dos caracteres.",
    },
  ],
};
const dateField = {
  fieldKey: "birth-date",
  label: "Fecha de nacimiento",
  kind: "date",
  order: 40,
  required: true,
  purpose: "dateOfBirth",
  helpText: "",
  errorMessage: "Ingresa una fecha de nacimiento válida.",
  rules: [
    {
      operator: "minimumAge",
      argument: { value: 18 },
      message: "El titular debe tener al menos 18 años.",
    },
  ],
};
const yearField = {
  fieldKey: "vehicle-year",
  label: "Año del vehículo",
  kind: "number",
  order: 60,
  required: true,
  purpose: "vehicleYear",
  helpText: "",
  errorMessage: "Ingresa el año del vehículo.",
  rules: [
    {
      operator: "vehicleYearRange",
      message: "Ingresa un año entre hace 20 años y el próximo año.",
    },
  ],
};
const makeField = {
  fieldKey: "vehicle-make",
  label: "Marca",
  kind: "select",
  order: 70,
  required: true,
  helpText: "",
  errorMessage: "Selecciona una marca.",
  options: makeOptions,
};
const accessoriesField = {
  fieldKey: "accessories",
  label: "El auto tiene accesorios adicionales",
  kind: "checkbox",
  order: 80,
  required: false,
  helpText: "",
  errorMessage: "Revisa esta opción.",
  defaultValue: { value: false },
};
const documentTypeField = {
  fieldKey: "document-type",
  label: "Tipo de documento",
  kind: "select",
  order: 20,
  required: true,
  helpText: "",
  errorMessage: "Selecciona un tipo de documento.",
  options: [
    { optionKey: "cc", label: "Cédula de ciudadanía" },
    { optionKey: "ce", label: "Cédula de extranjería" },
  ],
};

export function seedForm(country: Country) {
  const isColombia = country === "co";
  const documentField = {
    fieldKey: "identity-document",
    label: isColombia ? "Número de documento" : "RUT",
    kind: "text",
    order: 30,
    required: true,
    purpose: "identityDocument",
    helpText: "Usa un número ficticio.",
    errorMessage: "Ingresa el número de documento.",
  };
  const plateField = {
    fieldKey: "license-plate",
    label: isColombia ? "Placa" : "Patente",
    kind: "text",
    order: 50,
    required: true,
    purpose: "licensePlate",
    helpText: "",
    errorMessage: isColombia ? "Ingresa la placa." : "Ingresa la patente.",
  };
  return {
    country,
    fields: [
      nameField,
      ...(isColombia ? [documentTypeField] : []),
      documentField,
      dateField,
      plateField,
      yearField,
      makeField,
      accessoriesField,
    ],
  };
}
import { resolve } from "node:path";

import type { ConfigContext } from "./environment";

export default ({ env }: ConfigContext) => ({
  connection: {
    client: "sqlite",
    connection: {
      filename: resolve(env("DATABASE_FILENAME", ".data/strapi.sqlite")),
    },
    useNullAsDefault: true,
  },
});
services:
  cms:
    build:
      context: .
      target: cms
    environment:
      DATABASE_FILENAME: /data/strapi.sqlite
      STRAPI_TELEMETRY_DISABLED: "true"
    volumes:
      - strapi-content:/data
    ports:
      - "127.0.0.1:1337:1337"
    healthcheck:
      test:
        [
          "CMD",
          "node",
          "-e",
          "fetch('http://127.0.0.1:1337/_health').then(r=>process.exit(r.status===204?0:1)).catch(()=>process.exit(1))",
        ]
      interval: 4s
      timeout: 3s
      retries: 15
      start_period: 10s
  web:
    build:
      context: .
      target: web
    depends_on:
      cms:
        condition: service_healthy
    ports:
      - "127.0.0.1:8080:80"

