const script = String.raw`import assert from "node:assert/strict";
import { randomBytes, createHash } from "node:crypto";
import { once } from "node:events";
import { mkdtemp, rm } from "node:fs/promises";
import { createServer } from "node:http";
import { createRequire } from "node:module";
import { tmpdir } from "node:os";
import { join, resolve } from "node:path";

const root = process.cwd();
const rootRequire = createRequire(join(root, "package.json"));
const cmsRequire = createRequire(join(root, "backend", "package.json"));
const { chromium, expect } = rootRequire("@playwright/test");
const { createStrapi, compileStrapi } = cmsRequire("@strapi/strapi");
const apiPath = "/api/quote-content/v1/co/form";
const temp = await mkdtemp(join(tmpdir(), "us01-live-publish-"));
const secret = () => randomBytes(32).toString("hex");
Object.assign(process.env, {
  DATABASE_FILENAME: join(temp, "strapi.sqlite"),
  STRAPI_TELEMETRY_DISABLED: "true",
  HOST: "127.0.0.1",
  APP_KEYS: [secret(), secret()].join(","),
  ADMIN_JWT_SECRET: secret(),
  API_TOKEN_SALT: secret(),
  JWT_SECRET: secret(),
  TRANSFER_TOKEN_SALT: secret(),
  ENCRYPTION_KEY: secret(),
});

let app;
let browser;
let proxy;
try {
  const context = await compileStrapi({ appDir: resolve(root, "backend") });
  app = createStrapi(context);
  await app.load();

  const cmsServer = app.server.httpServer;
  const cmsListening = once(cmsServer, "listening");
  app.server.listen(0, "127.0.0.1");
  await cmsListening;
  const cmsAddress = cmsServer.address();
  assert.ok(cmsAddress && typeof cmsAddress === "object");
  const cmsOrigin = "http://127.0.0.1:" + cmsAddress.port;

  const documents = app.documents("api::quote-content.form-configuration");
  const draft = await documents.findFirst({
    status: "draft",
    filters: { country: "co" },
    populate: { fields: { populate: ["options", "rules"] } },
  });
  assert.ok(draft);
  const initial = await fetch(cmsOrigin + apiPath);
  assert.equal(initial.status, 200);
  const initialConfig = await initial.json();
  assert.equal(
    initialConfig.fields.some((field) => field.id === "agency"),
    false,
  );

  let apiReads = 0;
  const frontendOrigin = "http://127.0.0.1:8080";
  proxy = createServer(async (request, response) => {
    try {
      const isFormRead = request.url === apiPath;
      const upstreamOrigin = isFormRead ? cmsOrigin : frontendOrigin;
      if (isFormRead) apiReads += 1;
      if (request.method !== "GET" && request.method !== "HEAD") {
        response.writeHead(405);
        response.end();
        return;
      }
      const upstream = await fetch(upstreamOrigin + request.url, {
        method: request.method,
        headers: { accept: request.headers.accept ?? "*/*" },
      });
      response.statusCode = upstream.status;
      const contentType = upstream.headers.get("content-type");
      if (contentType) response.setHeader("content-type", contentType);
      const cacheControl = upstream.headers.get("cache-control");
      if (cacheControl) response.setHeader("cache-control", cacheControl);
      response.end(
        request.method === "HEAD"
          ? undefined
          : Buffer.from(await upstream.arrayBuffer()),
      );
    } catch {
      response.writeHead(502, { "content-type": "text/plain" });
      response.end("Local QA proxy failed");
    }
  });
  const proxyListening = once(proxy, "listening");
  proxy.listen(0, "127.0.0.1");
  await proxyListening;
  const proxyAddress = proxy.address();
  assert.ok(proxyAddress && typeof proxyAddress === "object");
  const origin = "http://127.0.0.1:" + proxyAddress.port;

  browser = await chromium.launch({ channel: "chrome", headless: true });
  const page = await browser.newPage();
  await page.goto(origin + "/co/quote/details");
  await page.getByLabel("Número de documento").waitFor({ state: "visible" });
  await expect(page.getByLabel("Agencia publicada en vivo")).toHaveCount(0);
  await page.getByLabel("Número de documento").fill("QA-LIVE-01");

  const bundleBefore = await page
    .locator('script[src*="main"]')
    .getAttribute("src");
  assert.ok(bundleBefore);
  const bundleBeforeResponse = await fetch(new URL(bundleBefore, origin));
  assert.equal(bundleBeforeResponse.status, 200);
  const bundleBeforeHash = createHash("sha256")
    .update(Buffer.from(await bundleBeforeResponse.arrayBuffer()))
    .digest("hex");

  const updatedFields = draft.fields.map((field) =>
    field.fieldKey === "identity-document"
      ? {
          ...field,
          label: "Identificación publicada en vivo",
          helpText: "Campo modificado en la instancia CMS desechable.",
        }
      : field,
  );
  updatedFields.push({
    fieldKey: "agency",
    label: "Agencia publicada en vivo",
    helpText: "",
    errorMessage: "Revisa la agencia.",
    kind: "text",
    required: false,
    order: 45,
  });
  await documents.update({
    documentId: draft.documentId,
    status: "draft",
    data: { fields: updatedFields },
  });
  await documents.publish({ documentId: draft.documentId });

  const livePublished = await fetch(cmsOrigin + apiPath);
  assert.equal(livePublished.status, 200);
  const liveConfiguration = await livePublished.json();
  assert.equal(
    liveConfiguration.fields.find((field) => field.id === "identity-document")
      .label,
    "Identificación publicada en vivo",
  );
  assert.equal(
    liveConfiguration.fields.some((field) => field.id === "agency"),
    true,
  );

  await page.reload();
  await expect(
    page.getByLabel("Identificación publicada en vivo"),
  ).toHaveValue("QA-LIVE-01");
  await expect(page.getByLabel("Agencia publicada en vivo")).toBeVisible();

  const bundleAfter = await page
    .locator('script[src*="main"]')
    .getAttribute("src");
  assert.equal(bundleAfter, bundleBefore);
  const bundleAfterResponse = await fetch(new URL(bundleAfter, origin));
  assert.equal(bundleAfterResponse.status, 200);
  const bundleAfterHash = createHash("sha256")
    .update(Buffer.from(await bundleAfterResponse.arrayBuffer()))
    .digest("hex");
  assert.equal(bundleAfterHash, bundleBeforeHash);
  assert.equal(apiReads, 2);

  console.log(
    JSON.stringify({
      result: "PASS",
      apiReads,
      changedPublishedLabel: "Identificación publicada en vivo",
      addedPublishedField: "Agencia publicada en vivo",
      retainedFictitiousDraft: true,
      bundleUrlUnchanged: true,
      bundleSha256Unchanged: bundleBeforeHash,
      browserOrigin: origin,
      frontendUpstream: frontendOrigin,
      cmsDatabase: "disposable SQLite",
    }),
  );
} finally {
  if (browser) await browser.close();
  if (proxy) await new Promise((resolveClose) => proxy.close(resolveClose));
  if (app) await app.destroy();
  await rm(temp, { recursive: true, force: true });
}
`;
